{"byte_size":417,"content":""""Stock reservations for the example catalog."""

from __future__ import annotations

STOCK: dict[str, int] = {"fern-01": 4, "moss-02": 0}


def reserve(sku: str, quantity: int) -> int:
    """Reserve stock and return what is left."""
    available = STOCK.get(sku, 0)
    if quantity > available:
        raise ValueError(f"not enough stock for {sku!r}")
    STOCK[sku] = available - quantity
    return STOCK[sku]
